import "server-only";
import data from "@/data/catalog.json";
import type { Card } from "./format";

/** Generated by scripts/catalog.py from the old OpenCart shop. Server-only. */
export type Review = { n: string; d: string | null; t: string; r: number };
export type Variant = { t: string; o: { v: string; s: string; on: boolean }[] };
export type Product = {
  id: number;
  slug: string;
  oldSlug: string;
  name: string;
  price: number;
  old: number | null;
  section: string;
  sub: string | null;
  brand: string | null;
  stock: boolean;
  color: string | null;
  con: string | null;
  country: string | null;
  dims: string | null;
  power: string | null;
  area: string | null;
  warranty: string | null;
  imgs: [string, number][];
  specs: [string, string][];
  variants: Variant[];
  desc: [string, string][];
  video: string | null;
  reviews: Review[];
  rating: number | null;
  popular: boolean;
  code: string | null;
};
export type Sub = { id: string; name: string; count: number };
export type Section = { id: string; old: string; name: string; short: string; lead: string; count: number; subs: Sub[] };
export type Brand = { id: string; name: string; country: string; line: string; count: number };
export type Post = { slug: string; old: string; title: string; cover: boolean; mins: number; desc: [string, string][] };

export const products = data.products as unknown as Product[];
export const sections = data.sections as Section[];
export const brands = data.brands as Brand[];
export const posts = data.blog as unknown as Post[];

const bySlug = new Map(products.map((p) => [p.slug, p]));
const byId = new Map(products.map((p) => [p.id, p]));
const brandName = new Map(brands.map((b) => [b.id, b.name]));

export const getProduct = (slug: string) => bySlug.get(slug);
export const getById = (id: number) => byId.get(id);
export const getSection = (id: string) => sections.find((s) => s.id === id);
export const getBrand = (id: string) => brands.find((b) => b.id === id);
export const getPost = (slug: string) => posts.find((p) => p.slug === slug);
export const subName = (sec: string, sub: string | null) => (sub ? getSection(sec)?.subs.find((s) => s.id === sub)?.name : undefined);

export function toCard(p: Product): Card {
  return {
    id: p.id,
    s: p.slug,
    n: p.name,
    p: p.price,
    o: p.old,
    b: p.brand,
    bn: p.brand ? (brandName.get(p.brand) ?? null) : null,
    sec: p.section,
    sub: p.sub,
    st: p.stock,
    d: p.dims,
    w: p.power,
    col: p.color,
    con: p.con,
    cty: p.country,
    img: p.imgs.length,
    k: (p.imgs[0]?.[0] as Card["k"]) ?? null,
    k2: (p.imgs[1]?.[0] as Card["k"]) ?? null,
    ...(p.popular ? { hot: true } : {}),
  };
}

/** Cards by id, in the given order; unknown ids are skipped. */
export const cards = (ids: number[]) => ids.map((id) => byId.get(id)).filter((p): p is Product => Boolean(p)).map(toCard);

export const allCards = () => products.map(toCard);
export const saleCards = () => products.filter((p) => p.old).sort((a, b) => b.old! / b.price - a.old! / a.price).map(toCard);

/** Same sub-category first, then same brand, then same section; size variants of the same model are left out (they have the picker). */
export function related(p: Product, n = 8) {
  const variants = new Set(p.variants.flatMap((v) => v.o.map((o) => o.s)));
  const score = (q: Product) => (q.sub && q.sub === p.sub ? 3 : 0) + (q.brand && q.brand === p.brand ? 1.5 : 0) + (q.imgs.length ? 0.5 : 0) + (q.stock ? 0.4 : 0);
  return products
    .filter((q) => q.id !== p.id && q.section === p.section && !variants.has(q.slug))
    .map((q) => ({ q, s: score(q) - Math.abs(Math.log((q.price || 1) / (p.price || 1))) * 0.4 }))
    .sort((a, b) => b.s - a.s)
    .slice(0, n)
    .map((x) => toCard(x.q));
}

/** Every customer review from the old product pages, newest first, with the product it belongs to. */
export function allReviews() {
  return products
    .flatMap((p) => p.reviews.map((r) => ({ ...r, product: p.name, slug: p.slug, id: p.id })))
    .filter((r) => r.t.length > 60 && r.r >= 4 && !/[ыэёъ]/i.test(r.t))
    .sort((a, b) => (b.d ?? "").localeCompare(a.d ?? ""));
}

export const reviewCount = () => products.reduce((n, p) => n + p.reviews.length, 0);
